const fs=require('node:fs'),vm=require('node:vm'),crypto=require('node:crypto');
const base='/tmp/mvc-ai-owner-rehearsal-2026-11-04';
const script=fs.readFileSync('src/meta_vibe_coding/static/app.js','utf8');
const ids=[...fs.readFileSync('src/meta_vibe_coding/static/index.html','utf8').matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]);
class Element {
 constructor(){this.value='';this.hidden=false;this.disabled=false;this.children=[];this.text='';this.handlers=new Map();}
 set textContent(x){this.text=x;this.children=[];}
 get textContent(){return this.text+this.children.map(c=>c.textContent).join(' ');}
 append(...x){this.children.push(...x);}
 replaceChildren(...x){this.text='';this.children=x;}
 addEventListener(type,fn){this.handlers.set(type,fn);}
}
const response=x=>({ok:true,json:async()=>structuredClone(x)});
(async()=>{
 const input=JSON.parse(fs.readFileSync(base+'/scenario-snapshots.json','utf8'));
 const rendered=[];
 for(const scenario of input.scenarios){
  const stages=[];
  for(const snap of scenario.stages){
   const els=new Map(ids.map(id=>[id,new Element()]));let exportCalls=0;
   const context={structuredClone,crypto:crypto.webcrypto,Blob,setTimeout,URL:{createObjectURL(){throw Error('No download executed');},revokeObjectURL(){}},confirm:()=>false,
    fetch:async(path,options)=>{
     if(path==='/api/config')return response({agent:'recorded replay',enabled:true,data_notice:'Synthetic replay; no product agent calls.',allowance_notice:'No live request.',limits:{request_seconds:300}});
     if(path==='/api/export'){
      exportCalls++;const state=JSON.parse(options.body);if(snap.export===null||state.revision!==snap.state.revision)throw Error('Unexpected export');return response(snap.export);
     }
     throw Error('No live route: '+path);
    },document:{getElementById:id=>els.get(id),createElement:()=>new Element()},snapshot:snap.state,prior:snap.previous,
    recordedStatus:snap.error?.message||'Updated. Check the interpretation and any open decisions.'};
   vm.createContext(context);vm.runInContext(script,context,{filename:'app.js'});await new Promise(r=>setImmediate(r));
   vm.runInContext('state=snapshot;previousResult=prior;pending=false;status(recordedStatus);',context);await vm.runInContext('render()',context);
   const el=id=>els.get(id);const sections=[];const nodes=el('owner').children;
   for(let i=0;i<nodes.length;i+=2)sections.push({heading:nodes[i].textContent,items:nodes[i+1].children.map(c=>c.textContent)});
   const brief=el('brief').textContent;
   if(snap.export!==null){if(exportCalls!==1||el('download').disabled)throw Error('Expected one export and enabled download');if(JSON.stringify(JSON.parse(brief))!==JSON.stringify(snap.export))throw Error('Brief mismatch');}
   else if(exportCalls!==0||!el('download').disabled)throw Error('Failed state must have no export');
   stages.push({label:snap.label,original_goal:el('original').textContent,recorded_owner_reply:snap.recorded_owner_reply,
    disposition:el('disposition').textContent,status:el('status').textContent,owner_sections:sections,
    question:el('clarification').hidden?null:{text:el('question').textContent,why:el('why').textContent},
    controls:{download_enabled:!el('download').disabled,unknown_enabled:!el('clarification').hidden&&!el('unknown').disabled,
     provisional_visible:!el('provisional').hidden,retry_visible:!!snap.error},
    developer_pane:brief,export_calls_in_double:exportCalls,actual_browser:false,download_executed:false});
  }
  rendered.push({id:scenario.id,persona:scenario.persona,source:scenario.source,stages});
 }
 const result={kind:'synthetic-controller-replay',controller_sha256:crypto.createHash('sha256').update(script).digest('hex'),scenarios:rendered,
  scope:'Current production controller in a DOM/HTTP double reading actual recorded states/exports. No real browser, click, download, product inference or participant.'};
 fs.writeFileSync(base+'/rendered-views.json',JSON.stringify(result,null,2)+'\n');
 const prompts=[['recommendation','What is recommended, and why?'],['data_access','Who can access which information, and what is still uncertain?'],['costs','What costs are known or unknown?'],['maintenance_recovery','What must you maintain, and what would you do if something went wrong?'],['next_action','What is your next action or unresolved decision?']];
 for(const scenario of rendered){
  const pack={kind:'synthetic-reader-replay-pack',simulation_id:scenario.id,persona:scenario.persona,
   instructions:['You are an AI simulating a fictional non-expert reader. Do not claim to be an actual human or give participant consent.',
    'Read only this pack. Do not inspect repository files, other simulations, acceptance rubrics, tests or expected answers. Do not use network or run the app.',
    'This is a replay of two recorded states, not an interactive branch controlled by your answers. Intermediate calls may be omitted. A proposed reply/correction is not applied to the product.',
    'Give your first teach-back before any feedback. State uncertainty when the view does not answer; do not manufacture mistakes to fit the persona and do not repair the product silently.',
    'Use final displayed state for teach-back, remembering that outdated content may describe earlier advice. Developer JSON is not supplied in this first reading.',
    'All actions are intended only. Do not report a click, browser task, saved file or recovery as executed. Confidence labels are generated self-reports, not human measurements.'],
   stages:scenario.stages.map(({developer_pane,...s})=>s),teach_back_prompts:prompts,
   requested_output:{simulation_id:scenario.id,synthetic:true,first_teach_back:prompts.map(([topic,prompt])=>({topic,prompt,answer:'your answer',confidence:'low|medium|high',visible_evidence:'section or status wording supporting the answer'})),
    intended_actions:[{task:'answer a displayed question',action:'what you would type or whether none is outstanding',executed:false},{task:'correct a requirement',action:'one fictional correction you would propose; no updated result may be assumed',executed:false},{task:'save the engineering brief',action:'what you would do given the final controls',executed:false}],questions_you_would_ask:[],unclear_or_potentially_misleading_wording:[],limits:'AI simulation; no human or actual browser task'}};
  fs.writeFileSync(base+'/'+scenario.id+'-reader-pack.json',JSON.stringify(pack,null,2)+'\n');
 }
 console.log('Rendered six states with production controller in doubles; five actual exports agree, one failed state remains unexportable. Three blinded Owner View packs created.');
})().catch(e=>{console.error(e);process.exit(1);});

